// Minimal sketch of a bounded queue used for backpressure
class BoundedQueue {
  constructor(limit) { this.limit = limit; this.q = []; }
  push(x) { if (this.q.length >= this.limit) return false; this.q.push(x); return true; }
  pop() { return this.q.shift(); }
}
